#!/bin/bash
# scan3.sh: rebuild file lists, then for each pattern print "cat|tool|n|repo1 repo2..." to stdout and first hit lines to hits.txt
D=$(dirname "$0")  # expects ./oss with the clones, see fetch.sh; cd $D/oss; mkdir -p $D/lists3; : > $D/hits3.txt
for d in */; do d=${d%/}; { find $d/.github $d/.circleci -type f 2>/dev/null; find $d -type f \( -name package.json -o -name 'playwright.config.*' -o -name 'stryker.conf*' -o -name '.dependency-cruiser*' -o -name 'lighthouserc*' -o -name sonar-project.properties -o -name '.snyk' -o -name socket.yml -o -name pyproject.toml -o -name .pre-commit-config.yaml -o -name '.golangci.y*ml' -o -name mypy.ini -o -name ruff.toml -o -name '.semgrep*' -o -name 'renovate.json*' -o -name 'knip.*' -o -name 'codecov.yml' -o -name '.codecov.yml' -o -name Gemfile -o -name .rubocop.yml -o -name composer.json -o -name 'phpstan.neon*' -o -name 'psalm.xml*' -o -name 'infection.json*' -o -name pom.xml -o -name 'build.gradle*' -o -name 'settings.gradle*' -o -name Cargo.toml -o -name deny.toml -o -name mix.exs -o -name .credo.exs -o -name tox.ini -o -name setup.cfg -o -name noxfile.py -o -name Directory.Build.props -o -name dotnet-tools.json -o -name 'requirements*.txt' \) -not -path '*/.git/*'; find $d -maxdepth 1 -type f; } | grep -viE '/dist/|\.min\.js$|lock|changelog|\.md$|/LICENSE|\.gitignore$|labels\.yml$|CODEOWNERS$|\.mailmap$' | sort -u > $D/lists3/$d.txt; done
while IFS='|' read -r cat name rx; do out=""; n=0
  for l in $D/lists3/*.txt; do r=$(basename $l .txt); f=$(xargs -a $l -d '\n' grep -lE -i -- "$rx" 2>/dev/null | head -1)
    if [ -n "$f" ]; then out="$out $r"; n=$((n+1)); echo "[$name] $f: $(grep -m1 -oiE ".{0,40}($rx).{0,40}" "$f" | head -1)" >> $D/hits3.txt; fi; done
  echo "$cat|$name|$n|$out"; done < $D/patterns3.txt
